import{_ as a,c as o,a3 as r,o as t}from"./chunks/framework.C-yY9WsR.js";const m=JSON.parse('{"title":"Windows 面板安装","description":"","frontmatter":{},"headers":[],"relativePath":"guide/Windows-面板安装.md","filePath":"guide/Windows-面板安装.md"}'),i={name:"guide/Windows-面板安装.md"};function d(l,e,n,s,p,c){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="windows-面板安装" tabindex="-1">Windows 面板安装 <a class="header-anchor" href="#windows-面板安装" aria-label="Permalink to &quot;Windows 面板安装&quot;">​</a></h1><p>适用于 Windows 10/11 x64。下载包已包含 Python 和运行所需的依赖，无需预先安装 Python，也无需在首次启动时下载依赖。</p><h2 id="安装与启动" tabindex="-1">安装与启动 <a class="header-anchor" href="#安装与启动" aria-label="Permalink to &quot;安装与启动&quot;">​</a></h2><ol><li>打开 <a href="https://github.com/emby-keeper/emby-keeper/releases" target="_blank" rel="noreferrer">Embykeeper Releases</a>，下载最新版本中的 <code>embykeeper-win-vx.x.x.zip</code>。</li><li>将 ZIP 完整解压到自己的文件夹，双击 <code>Start-Embykeeper.bat</code>。不要直接在压缩包内运行，也不要单独移动启动文件。</li><li>按窗口提示设置面板登录密码。输入时密码不会显示；请记住该密码，不能使用 <code>your-password</code>。</li><li>等待浏览器自动打开，使用刚设置的密码登录并添加账号。</li></ol><p>启动后，Embykeeper 会留在屏幕右下角的系统托盘。点击图标可打开网页；右键选择 <strong>Exit</strong> 可退出。再次双击启动文件会打开已运行的面板。</p><p>面板默认仅允许本机通过 <a href="http://127.0.0.1:8000" target="_blank" rel="noreferrer">http://127.0.0.1:8000</a> 访问。关闭浏览器不会停止程序。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><p>先从托盘退出，然后将最新版本的 ZIP 解压到一个新文件夹，双击其中的 <code>Start-Embykeeper.bat</code>。已有账号、设置和面板密码会保留。不要将不同版本的运行文件混在同一个文件夹里。</p><h2 id="忘记密码" tabindex="-1">忘记密码 <a class="header-anchor" href="#忘记密码" aria-label="Permalink to &quot;忘记密码&quot;">​</a></h2><p>先从托盘退出，在文件资源管理器地址栏输入 <code>%LOCALAPPDATA%\\Embykeeper</code>，删除其中的 <code>panel-password.txt</code>。再次双击启动文件，按提示设置新密码。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li>启动时提示缺少文件：重新完整解压 ZIP，保留启动文件旁的 <code>runtime</code> 文件夹。</li><li>网页未打开：确认本机 8000 端口未被其他程序占用；启动日志位于 <code>%LOCALAPPDATA%\\Embykeeper\\panel.log</code>。</li><li>托盘图标不可见：展开任务栏通知区域中的隐藏图标。</li></ul><p>如果需要在线安装，可下载 <code>embykeeper-win-online-vx.x.x.zip</code>。这个较小的包会在首次运行时下载 Python 并通过 pip 安装依赖，耗时取决于网络和磁盘速度；国内源不可用时会尝试官方源。</p><p>账号数据和密码属于敏感信息，请妥善保护本机用户账户及备份。</p>',14)]))}const b=a(i,[["render",d]]);export{m as __pageData,b as default};
